# Masks as row/column colored-cell coordinates for demo 3.
A3={(0,3),(1,1),(1,2),(1,3),(2,1),(3,1),(3,2),(3,3),(4,1)}
B3={(0,2),(1,1),(1,2),(1,3),(2,1),(2,3),(3,1),(3,3),(4,3)}
C3={(0,1),(1,1),(1,2),(1,3),(2,3),(3,1),(3,2),(3,3)}
D3={(1,1),(1,2),(1,3),(2,1),(2,3),(3,1),(3,2),(3,3),(0,2),(4,2)}
O3=[D3,B3,A3,C3]
def transforms(s):
    variants=[]
    for k in range(4):
        t=s
        for _ in range(k): t={(c,4-r) for r,c in t}
        variants.append(('rot'+str(k*90),t))
        variants.append(('mirrorrot'+str(k*90),{(r,4-c) for r,c in t}))
    return variants
for oi,o in enumerate(O3):
    matches=[]
    for name,s in [('A',A3),('B',B3),('C',C3),('D',D3)]:
        matches += [(name,tr) for tr,v in transforms(s) if v==o]
    print(oi,matches)
